import { styleText } from 'node:util';
import { Args, Flags } from '@oclif/core';
import { assertReadableModel, isTerminalStage, } from '@sanity/workflow-engine';
import { WorkflowCommand } from '../../../lib/base-command.js';
import { ambiguityFor, resolveReadTargets, soleHitOrChoose, } from '../../../lib/context.js';
import { buildDefinitionShowQuery, buildDefinitionPartitionsQuery } from '../../../lib/definitions.js';
import { fail } from '../../../lib/fail.js';
import { jsonFlags, readFlags, resourceFlags } from '../../../lib/flags.js';
import { formatKeyValue, searchedScope, sectionHeader } from '../../../lib/ui.js';
export default class DefinitionShow extends WorkflowCommand {
    static hiddenAliases = ['workflows:definition:show'];
    static description = 'Show a deployed workflow definition.';
    static args = {
        name: Args.string({ required: true, description: 'Workflow definition name.' }),
    };
    static flags = {
        ...readFlags,
        ...resourceFlags,
        version: Flags.integer({ description: 'Specific version (default: latest).' }),
        ...jsonFlags,
    };
    async run() {
        const { args, flags } = await this.parse(DefinitionShow);
        const { targets, partition } = await resolveReadTargets(flags);
        const def = await resolveShownDefinition({
            targets,
            name: args.name,
            partition,
            version: flags.version,
            ambiguity: ambiguityFor(flags),
        });
        if (!def) {
            const scope = searchedScope({
                partition,
                resources: targets.map(({ resource }) => resource),
                deployment: flags.deployment,
            });
            fail(`no definition "${args.name}" (${versionLabel(flags.version)}) ${scope}`);
        }
        if (flags.json) {
            this.log(JSON.stringify(def, null, 2));
            return;
        }
        this.log(definitionHeader(def, def.tag));
        this.log('');
        for (const line of describeDefinition(def)) {
            this.log(line);
        }
    }
}
export async function resolveShownDefinition({ targets, name, partition, version, ambiguity, choose, }) {
    const candidates = partition === undefined
        ? await partitionCandidates({ targets, name })
        : targets.map((target) => ({ ...target, partition }));
    const hits = await fetchDefinitionHits({ candidates, name, version });
    const sole = await soleHitOrChoose(hits, {
        subject: `Definition "${name}"`,
        partitionOf: (hit) => hit.partition,
        ambiguity,
        ...(choose === undefined ? {} : { choose }),
    });
    return sole?.def;
}
export function versionLabel(version) {
    return version === undefined ? 'latest' : `v${version}`;
}
async function partitionCandidates({ targets, name, }) {
    const { groq, params } = buildDefinitionPartitionsQuery(name);
    const perTarget = await Promise.all(targets.map(async (target) => {
        const partitions = await target.client.fetch(groq, params, {
            tag: 'definition.show',
        });
        return partitions.map((held) => ({ ...target, partition: held }));
    }));
    return perTarget.flat();
}
export async function fetchDefinitionHits({ candidates, name, version, }) {
    const probes = await Promise.all(candidates.map(async (candidate) => {
        const { groq, params } = buildDefinitionShowQuery({
            name,
            partition: candidate.partition,
            version,
        });
        const def = await candidate.client.fetch(groq, params, {
            tag: 'definition.show',
        });
        return def === null ? undefined : { ...candidate, def: assertReadableModel(def) };
    }));
    return probes.filter((hit) => hit !== undefined);
}
const HEADER_PAD = 11;
export function definitionHeader(def, partition) {
    const rows = [
        formatKeyValue({ key: 'Title', value: def.title, padTo: HEADER_PAD }),
        formatKeyValue({
            key: 'Description',
            value: def.description ?? styleText('dim', '—'),
            padTo: HEADER_PAD,
        }),
    ];
    if (partition !== undefined) {
        rows.push(formatKeyValue({ key: 'Partition', value: partition, padTo: HEADER_PAD }));
    }
    return [styleText('bold', `${def.name} v${def.version}`), ...rows].join('\n');
}
function actionLine(action) {
    const statusOp = (action.ops ?? []).find((op) => op.type === 'status.set');
    const status = statusOp ? styleText('dim', ` → ${statusOp.status}`) : '';
    return `          · ${action.name}${status}`;
}
function activityBlock(activity) {
    const title = activity.title ? styleText('dim', ` — ${activity.title}`) : '';
    return [`      - ${activity.name}${title}`, ...(activity.actions ?? []).map(actionLine)];
}
function stageBlock(stage, initialStage) {
    const title = stage.title ? styleText('dim', ` — ${stage.title}`) : '';
    const terminal = isTerminalStage(stage) ? styleText('dim', ' (terminal)') : '';
    const initial = stage.name === initialStage ? styleText('cyan', '  [initial]') : '';
    return [
        `  • ${stage.name}${title}${terminal}${initial}`,
        ...(stage.activities ?? []).flatMap(activityBlock),
    ];
}
export function describeDefinition(def) {
    return [
        sectionHeader('Stages'),
        ...def.stages.flatMap((stage) => stageBlock(stage, def.initialStage)),
    ];
}
